TITLE_AR = "ACRS (نظام الاستجابة الآلية للاختراق): احتواء الهجمات السيبرانية في الأنظمة بأقل إجراء كافٍ وآمن، مع تجربة على حاسوب كمّي حقيقي"
TITLE_EN = "ACRS (Automated Compromise Response System): Safety-Gated Minimum-Action Cyberattack Containment, with a Real Quantum-Hardware Demonstration"
MAIN_CAT = "تصميم البرمجيات - Software Design"
SUB_CAT = "الأمن السيبراني (Cybersecurity)"

S1 = [
    "عندما يُكتشف هجوم سيبراني، تعزل أنظمة الاستجابة الآلية الجهاز المشتبه به عزلًا كاملًا، وفي الأنظمة الحيوية قد يوقف هذا العزل خدمات سليمة يعتمد عليها الناس. ففي هجوم WannaCry على النظام الصحي البريطاني تعطلت 46 جهة صحية لم تكن مصابة أصلًا [1].",
    "بنينا في هذا البحث نظام ACRS، وصغنا قرار الاحتواء للشبكة كاملة كمسألة تحسين ثنائية (QUBO) اختارت أقل إجراء يكفي لإيقاف الهجوم: عزل، أو تقييد، أو «تجزئة» للخادم الحرج أبقت خدمته تعمل. ومرّ كل قرار عبر بوابة سلامة مستقلة عن المُحسِّن أحالت القرارات الحرجة لموافقة شخصين بدل أن تفشل بصمت.",
    "من الإصدار الثاني سجّلنا معايير النجاح في Git قبل كل تجربة، واختبرنا على أكثر من 4,000 سيناريو هجوم لم يُصمَّم عليها النظام، وعلى جدار حماية Linux حقيقي، وعلى حواسيب IBM الكمّية. على 259 سلسلة هجوم احتوى ACRS تلقائيًا 97.7% مما يحتويه العزل الكامل الآمن (الحد المسجل مسبقًا 80%)، مع 0 خدمات متوقفة مقابل 292 للعزل الكامل (وبعد موافقة البشر على الإحالات: 6 مقابل 273 على 253 سلسلة جديدة)، ودون أي فشل صامت. وتأكدت على بيانات جديدة (0.980، و0.995 في شبكة صحية من 60 جهازًا)، وبنفس المحرّك دون تغيير أي وزن تحققت في شبكة بنك (0.902) وجامعة (0.839)، وكانت أقل بقليل في مصنع صناعي (0.792). ثم شغّلنا المحرّك على هجمات حقيقية موثقة (8 حوادث منها WannaCry، ثم 75 حادثة من مصادر مفتوحة) فكشفت أن المُحسِّن وحده لا يتفوق على قاعدة بسيطة؛ وبعد إضافة «أرضية أمان» مسجّلة مسبقًا (v12) صار الاحتواء التلقائي 100% على الحوادث الثماني التي صُمّمت الأرضية بعدها، و91% من 207 لحظات في 75 حادثة جديدة، والخدمات المتوقفة بعد الموافقات أقل من القاعدة والعزل الكامل، دائمًا بشرط وصول التنبيه. وطابق السلوك الحقيقي النموذج في 6,002 فحص، وقُطع المهاجم خلال 41 مللي ثانية (p95) على السيناريوهات التركيبية و118 (فوق هدف 50) على 66 سيناريو حقيقي وواقعي، ولم تستطع التنبيهات المزوّرة إجبار النظام على إيقاف أي خدمة.",
    "وعلى العتاد الكمّي اكتشفنا أن عقوبة السلامة الكبيرة تخفي فروق التكلفة عن الدارة الكمّية، فأثبتنا أن «أصغر عقوبة آمنة» تحافظ على الحل نفسه. بعدها حلّ حاسوب IBM الجزء المترابط من قرار حادث في شبكة من أربعة مواقع (240 جهازًا، 75 من 132 متغيرًا): وجد الأمثل في 11 من 11 مسألة على جهازين، وطابق القرار النهائي الحل الدقيق. ونشرنا الأهداف التي لم تتحقق من أول مرة وكيف عالجناها، ولم ندّعِ تفوقًا كمّيًا. وكانت الشبكات الحقيقية مُعاد بناؤها جزئيًا من التقارير العامة، وأشارت النتائج إلى أن الأنظمة يمكن أن تحتوي الهجوم دون أن توقف خدماتها متى وصل التنبيه.",
]

